/* Generated by the standalone Vite build. Only the public app shell is cached. */
const CACHE_PREFIX = 'moyubot-pwa-shell-';
const CACHE = `${CACHE_PREFIX}__BUILD_ID__`;
const PRECACHE = __PRECACHE_FILES__;
const absolute = name => new URL(name, self.registration.scope).href;
const shellURLs = new Set(PRECACHE.map(absolute));
self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(PRECACHE.map(name => new Request(absolute(name), { cache: 'reload' })))));
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    await Promise.all((await caches.keys()).filter(key => key.startsWith(CACHE_PREFIX) && key !== CACHE).map(key => caches.delete(key)));
    await self.clients.claim();
  })());
});
self.addEventListener('message', event => {
  if (event.data?.type === 'ACTIVATE_UPDATE') self.skipWaiting();
});
self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  const scope = new URL(self.registration.scope);
  if (request.method !== 'GET' || url.origin !== scope.origin || !url.pathname.startsWith(scope.pathname)) return;
  if (/\/(api|auth)(\/|$)/.test(url.pathname)) return;
  if (request.mode === 'navigate') {
    // Keep HTML and hashed JS on the same release until the user accepts an update.
    event.respondWith(caches.open(CACHE).then(async cache => (await cache.match(absolute('index.html'))) || fetch(request)));
  } else if (shellURLs.has(url.href)) {
    event.respondWith(caches.open(CACHE).then(async cache => (await cache.match(request)) || fetch(request)));
  }
});
